window.DCBStore=(()=>{
const key='aikatsu-dcb-v01';const clamp=(n,max=999)=>Math.min(max,Math.max(0,Math.floor(Number(n)||0)));let state={},available=true;
try{state=JSON.parse(localStorage.getItem(key)||'{}');if(!state||typeof state!=='object'||Array.isArray(state))state={};}catch{available=false;}
const defaultRetain=()=>Math.max(1,clamp(state.__settings?.retainCount??1,5));
const normalize=(card,v={})=>{if(!v||typeof v!=='object')v={};const ownedCount=clamp(v.ownedCount??card.ownedCount),retainCount=Math.max(1,clamp(v.retainCount??defaultRetain(),5));return{ownedCount,retainCount,tradeCount:clamp(v.tradeCount,Math.max(0,ownedCount-retainCount)),favorite:typeof v.favorite==='boolean'?v.favorite:card.favorite,memo:typeof v.memo==='string'?v.memo.slice(0,2000):card.memo,updatedAt:Number(v.updatedAt)||0,registeredAt:Math.max(0,(v.registeredAt==null?Number(v.updatedAt):Number(v.registeredAt))||0)};};
return{get defaultRetain(){return defaultRetain();},setDefaultRetain(value){const count=Number(value);if(!Number.isInteger(count)||count<1||count>5)return false;const proposed={...state,__settings:{...state.__settings,retainCount:count}};for(const card of DCBData.cards)proposed[card.id]=normalize(card,{...this.get(card),retainCount:count});try{localStorage.setItem(key,JSON.stringify(proposed));state=proposed;available=true;return true;}catch{available=false;return false;}},get:card=>normalize(card,state[card.id]),update(card,patch){const previous=this.get(card),now=Date.now();const registeredAt=previous.registeredAt||((previous.ownedCount===0&&Number(patch.ownedCount)>0)?now:0);const next=normalize(card,{...previous,...patch,updatedAt:now,registeredAt});if(next.tradeCount>0&&previous.tradeCount===0&&DCBData.cards.filter(c=>this.get(c).tradeCount>0).length>=50)return false;const proposed={...state,[card.id]:next};try{localStorage.setItem(key,JSON.stringify(proposed));state=proposed;available=true;return true;}catch{available=false;return false;}},get available(){return available;},export(){return JSON.stringify({version:1,savedAt:new Date().toISOString(),inventory:Object.fromEntries(DCBData.cards.map(c=>[c.id,this.get(c)]))},null,2);}};})();
